        for j in range(W):
            if seen[i][j]: continue
            v=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; comp=[]
            while q:
                a,b=q.popleft(); comp.append((a,b))
                for da,db in nb:
                    x,y=a+da,b+db
                    if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==v:
                        seen[x][y]=True; q.append((x,y))
            comps.append((v,comp))
    area={}
    for v,comp in comps:
        if len(comp)>1:
            rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
            area[v]=(max(rs)-min(rs)+1)*(max(cs)-min(cs)+1)
    for v,comp in comps:
        if len(comp)==1:
            a,b=comp[0]
            votes={}
            for x,y in nb:
                if 0<=a+x<H and 0<=b+y<W:
                    vv=g[a+x][b+y]
                    if vv!=v:
                        votes.setdefault(vv,0); votes[vv]+=area.get(vv,0)
            if votes:
                mx=max(votes.values()); 
                cands=[k for k,vv in votes.items() if vv==mx]
                out[a][b]=max(cands,key=lambda k:area[k])
    return out
